$ErrorActionPreference='Stop'
$tmp=Join-Path $env:TEMP 'pc-iphone-sorted-p1.mjs'
try{
[System.IO.File]::WriteAllText($tmp,@'
setTimeout(()=>{console.log(JSON.stringify({error:'hard_timeout'}));process.exit(0)},9500);
try{const v=await(await fetch('http://127.0.0.1:17447/json/version')).json();const w=new WebSocket(v.webSocketDebuggerUrl);
await new Promise((ok,no)=>{w.addEventListener('open',ok,{once:true});w.addEventListener('error',no,{once:true})});
let seq=0;const pending=new Map();w.addEventListener('message',e=>{const z=JSON.parse(e.data);if(pending.has(z.id)){pending.get(z.id)(z);pending.delete(z.id)}});
const send=(method,params)=>Promise.race([new Promise(resolve=>{let id=++seq;pending.set(id,resolve);w.send(JSON.stringify({id,method,params}))}),new Promise(resolve=>setTimeout(()=>resolve({error:{message:'cdp_timeout'}}),3000))]);
const results=[];for(const url of ["https://www.avito.ru/krasnoyarsk/telefony/mobilnye_telefony/apple/iphone_15_pro_max-ASgBAgICA0SywA3Woe0RtMANzqs5sMENiPw3?s=1","https://www.avito.ru/krasnoyarsk/telefony/mobilnye_telefony/apple/iphone_16_pro_max-ASgBAgICA0SywA3MsYwVtMANzqs5sMENiPw3?s=1"]){const z=await send('Target.createTarget',{url,background:true,newWindow:false});results.push({target_id:z.result?.targetId||null,url,error:z.error?.message||null})}
let activation=null;if(results[0]?.target_id){const z=await send('Target.activateTarget',{targetId:results[0].target_id});activation=!!z.result}
console.log(JSON.stringify({results,firstActivated:activation}));process.exit(0);
}catch(e){console.log(JSON.stringify({error:String(e).slice(0,100)}));process.exit(0)}
'@,[System.Text.UTF8Encoding]::new($false))
& node.exe $tmp
} finally { Remove-Item $tmp -Force -ErrorAction SilentlyContinue }
